-- ────────────────────────────────────────────────────────────────────────────
-- VERIFICATION — scoped to THIS WAVE'S 73 roll calls and 3 slugs.
-- Nothing below counts a session-wide or corpus-wide total. A guard that fails because
-- some other wave landed is a guard that gets deleted, so every count here is taken over
-- the named rolls only. The roll ids live in an integer[] local rather than a temp table:
-- a data-only migration that sorts after the newest drizzle snapshot may not declare an
-- object, and scripts/test-vr-corrections.mjs reads any CREATE of a TABLE as a
-- declaration regardless of how temporary it is. The element type is vr_rollcalls.id.
-- ────────────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  n_rolls integer; n_cells integer; n_badpos integer; n_badparty integer; n_orphan integer;
  n_tally integer; n_chamber integer; n_rule11 integer; n_issues integer; n_measures integer;
  n_slug integer; n_energy integer; s text;
  roll_ids integer[];
BEGIN
  SELECT array_agg(id) INTO roll_ids FROM vr_rollcalls
   WHERE (chamber, congress, session, roll_number) IN (('senate',117,1,110), ('senate',117,1,314), ('senate',117,1,499), ('senate',117,2,71), ('senate',117,2,242), ('senate',117,2,271), ('senate',117,2,280), ('senate',117,2,325), ('senate',117,2,362), ('senate',117,2,396), ('senate',118,1,146), ('senate',118,1,171), ('senate',118,1,268), ('senate',118,1,343), ('senate',118,2,150), ('senate',118,2,154), ('senate',118,2,292), ('senate',118,2,293), ('senate',118,2,294), ('senate',118,2,325), ('senate',118,2,338), ('senate',119,1,3), ('senate',119,1,4), ('senate',119,1,6), ('senate',119,1,7), ('senate',119,1,15), ('senate',119,1,33), ('senate',119,1,52), ('senate',119,1,61), ('senate',119,1,95), ('senate',119,1,127), ('senate',119,1,128), ('senate',119,1,151), ('senate',119,1,153), ('senate',119,1,160), ('senate',119,1,165), ('senate',119,1,166), ('senate',119,1,238), ('senate',119,1,277), ('senate',119,1,281), ('senate',119,1,318), ('senate',119,1,328), ('senate',119,1,372), ('senate',119,1,411), ('senate',119,1,454), ('senate',119,1,455), ('senate',119,1,478), ('senate',119,1,554), ('senate',119,1,555), ('senate',119,1,563), ('senate',119,1,570), ('senate',119,1,608), ('senate',119,1,632), ('senate',119,1,648), ('senate',119,2,5), ('senate',119,2,46), ('senate',119,2,53), ('senate',119,2,58), ('senate',119,2,69), ('senate',119,2,79), ('senate',119,2,80), ('senate',119,2,81), ('senate',119,2,84), ('senate',119,2,88), ('senate',119,2,113), ('senate',119,2,118), ('senate',119,2,129), ('senate',119,2,156), ('senate',119,2,160), ('senate',119,2,163), ('senate',119,2,174), ('senate',119,2,207), ('senate',119,2,216));
  n_rolls := coalesce(array_length(roll_ids, 1), 0);
  IF n_rolls <> 73 THEN
    RAISE EXCEPTION 'Federal wave F8: expected 73 roll calls already on file, found %', n_rolls;
  END IF;

  -- The wave's own cells, counted exactly rather than as a floor. None of the three held
  -- a single cell anywhere in the corpus before this migration, so an exact count is
  -- available here and a floor would hide a partial insert.
  SELECT count(*) INTO n_cells FROM vr_member_votes
   WHERE rollcall_id = ANY(roll_ids) AND politician_id IN ('alan_armstrong', 'hyde_smith', 'jon_husted');
  IF n_cells <> 136 THEN
    RAISE EXCEPTION 'Federal wave F8: expected 136 cells for the three admitted senators on these rolls, found %', n_cells;
  END IF;

  -- And per slug, because the totals can be right while one senator's rows are missing.
  SELECT count(*) INTO n_slug FROM vr_member_votes
   WHERE rollcall_id = ANY(roll_ids) AND politician_id = 'alan_armstrong';
  IF n_slug <> 15 THEN
    RAISE EXCEPTION 'Federal wave F8: expected 15 cells for alan_armstrong (Alan Armstrong, LIS S440), found %', n_slug;
  END IF;
  SELECT count(*) INTO n_slug FROM vr_member_votes
   WHERE rollcall_id = ANY(roll_ids) AND politician_id = 'hyde_smith';
  IF n_slug <> 73 THEN
    RAISE EXCEPTION 'Federal wave F8: expected 73 cells for hyde_smith (Cindy Hyde-Smith, LIS S395), found %', n_slug;
  END IF;
  SELECT count(*) INTO n_slug FROM vr_member_votes
   WHERE rollcall_id = ANY(roll_ids) AND politician_id = 'jon_husted';
  IF n_slug <> 48 THEN
    RAISE EXCEPTION 'Federal wave F8: expected 48 cells for jon_husted (Jon Husted, LIS S438), found %', n_slug;
  END IF;

  -- The point of the wave, asserted where it cannot rot: each senator this wave says gains an
  -- energy act now holds at least one judged vote on a measure carrying one of the four
  -- energy keys as PRIMARY. If a later correction unmaps those measures this fires, and the
  -- wave's claim stops being true and silent at the same time.
  -- Scoped to hyde_smith, jon_husted and NOT to alan_armstrong, because the
  -- claim is not true of them and a guard that asserts a falsehood gets deleted rather than
  -- fixed. alan_armstrong was sworn 2026-03-24 and the Senate has held no contested
  -- roll on a measure carrying an energy key as PRIMARY since — the same emptiness the census
  -- found looking forward. He holds lands_energy and lands_preserve as SECONDARY keys only.
  FOREACH s IN ARRAY ARRAY['hyde_smith', 'jon_husted'] LOOP
    SELECT count(*) INTO n_energy FROM vr_member_votes v
     JOIN vr_rollcalls r ON r.id = v.rollcall_id
     JOIN vr_measure_issues mi ON mi.measure_id = r.measure_id
     WHERE v.politician_id = s AND v.position IN ('yea','nay') AND mi.is_primary
       AND mi.issue_key IN ('energy_production','permitting_reform','lands_energy','climate_action');
    IF n_energy < 1 THEN
      RAISE EXCEPTION 'Federal wave F8: % holds no judged vote on any measure carrying an energy key as PRIMARY. The wave exists to give the energy keys Senate attribution for these three.', s;
    END IF;
  END LOOP;

  SELECT count(*) INTO n_badpos FROM vr_member_votes
   WHERE rollcall_id = ANY(roll_ids) AND position NOT IN ('yea','nay','present','not_voting');
  IF n_badpos > 0 THEN
    RAISE EXCEPTION 'Federal wave F8: % member vote(s) carry a position outside the closed vocabulary.', n_badpos;
  END IF;

  SELECT count(*) INTO n_badparty FROM vr_member_votes
   WHERE rollcall_id = ANY(roll_ids) AND is_party IS NOT NULL
     AND is_party NOT IN ('with_party','against_party');
  IF n_badparty > 0 THEN
    RAISE EXCEPTION 'Federal wave F8: % member vote(s) carry an is_party outside the closed vocabulary.', n_badparty;
  END IF;

  -- Fail-closed attribution, asserted rather than assumed. A politician_id on one of these
  -- rolls that is not in the roster means the resolver guessed at somebody. This is the one
  -- guard the wave's own subject makes non-negotiable: the whole reason these three were
  -- missing is that the ingest refuses to attribute a vote it cannot identify, and a wave
  -- that adds roster slugs is exactly when that refusal is most tempting to soften.
  SELECT count(*) INTO n_orphan FROM vr_member_votes v
   WHERE v.rollcall_id = ANY(roll_ids)
     AND v.politician_id NOT IN ('adam_smith', 'adrian_smith', 'aguilar', 'alan_armstrong', 'alsobrooks', 'andy_harris', 'andy_kim', 'angie_craig', 'angus_king', 'aoc', 'arrington', 'ashley_moody', 'ayanna_pressley', 'banks', 'barrasso', 'bennet', 'bennie_thompson', 'blackburn', 'blumenthal', 'blunt_rochester', 'bmoore', 'boebert', 'booker', 'boozman', 'brendan_boyle', 'brian_babin', 'brian_mast', 'britt', 'bruce_westerman', 'bryan_steil', 'cantwell', 'capito', 'cassidy', 'chellie_pingree', 'chip_roy', 'chris_murphy', 'clyburn', 'collins', 'comer', 'coons', 'cortez_masto', 'cotton', 'crapo', 'crockett', 'cruz', 'cstewart', 'curtis', 'daines', 'dan_crenshaw', 'dan_goldman', 'dan_sullivan', 'deb_fischer', 'debbie_dingell', 'delauro', 'delia_ramirez', 'diana_degette', 'dina_titus', 'don_bacon', 'don_davis', 'donalds', 'duckworth', 'durbin', 'emmer', 'ernst', 'fetterman', 'fitzpatrick', 'foxx', 'frank_lucas', 'french_hill', 'gabe_vasquez', 'gaetz', 'gallego', 'garbarino', 'gillibrand', 'glenn_thompson', 'graham', 'grassley', 'greg_landsman', 'guthrie', 'hagerty', 'haley_stevens', 'hawley', 'heinrich', 'hickenlooper', 'hirono', 'hoeven', 'hyde_smith', 'jake_auchincloss', 'jan_schakowsky', 'jared_golden', 'jared_huffman', 'jason_smith', 'jayapal', 'jeffries', 'jerry_moran', 'jim_himes', 'jim_jordan', 'jim_justice', 'jim_mcgovern', 'john_cornyn', 'jon_husted', 'jon_ossoff', 'josh_brecheen', 'josh_gottheimer', 'julie_fedorchak', 'kaine', 'kclark', 'kennedy', 'kennedy_john', 'kevin_cramer', 'kevin_hern', 'khanna', 'klobuchar', 'lankford', 'lee', 'lujan', 'lummis', 'luna', 'maggie_hassan', 'maloy', 'mariannette_miller_meeks', 'marie_gluesenkamp_perez', 'mark_kelly', 'markey', 'massie', 'maxine_waters', 'maxwell_frost', 'mcclain', 'mcconnell', 'mccormick', 'meeks', 'melanie_stansbury', 'merkley', 'michael_guest', 'mike_bost', 'mike_collins', 'mike_ezell', 'mike_flood', 'mike_johnson', 'mike_lawler', 'mike_rounds', 'mike_simpson', 'mike_waltz', 'moreno', 'mtg', 'mullin', 'murkowski', 'murray', 'nadler', 'nancy_mace', 'neal', 'neguse', 'omar', 'owens', 'padilla', 'pallone', 'peters', 'raja_krishnamoorthi', 'rand_paul', 'raskin', 'reed', 'rick_crawford', 'rick_larsen', 'rick_scott', 'ricketts', 'risch', 'rob_bresnahan', 'robert_garcia', 'roger_marshall', 'roger_williams', 'ron_johnson', 'rosen', 'rubio', 'russ_fulcher', 'ryan_mackenzie', 'sam_graves', 'sanders', 'sarah_mcbride', 'scalise', 'schatz', 'schiff', 'schmitt', 'schumer', 'scott_perry', 'seth_moulton', 'shaheen', 'sheehy', 'slotkin', 'stefanik', 'steny_hoyer', 'stephanie_bice', 'steve_womack', 'summer_lee', 'susie_lee', 'takano', 'tammy_baldwin', 'ted_budd', 'ted_lieu', 'teresa_leger_fernandez', 'tgabbard', 'thune', 'tillis', 'tim_scott', 'tina_smith', 'tlaib', 'todd_young', 'tom_cole', 'tom_suozzi', 'tommy_tuberville', 'torres', 'trent_kelly', 'troy_downing', 'van_hollen', 'walberg', 'warner', 'warnock', 'warren', 'welch', 'whitehouse', 'wicker', 'wyden', 'zach_nunn', 'zeldin', 'zoe_lofgren');
  IF n_orphan > 0 THEN
    RAISE EXCEPTION 'Federal wave F8: % member vote(s) on these rolls carry a politician_id outside db/vr-member-map.json. Attribution here is fail-closed, so this is a bug, not a roster gap.', n_orphan;
  END IF;

  -- The tally is the chamber's, not the roster's. The subset check compares the yea+nay
  -- pool against the attributed rows carrying a JUDGED position, which genuinely is a
  -- subset of it — attributed rows also include not_voting, so on a near-unanimous roll
  -- the naive comparison is wrong in the other direction.
  SELECT count(*) INTO n_tally FROM vr_rollcalls r
   WHERE r.id = ANY(roll_ids)
     AND (r.totals->>'yea')::int + (r.totals->>'nay')::int
         < (SELECT count(*) FROM vr_member_votes v WHERE v.rollcall_id = r.id
             AND v.position IN ('yea','nay'));
  IF n_tally > 0 THEN
    RAISE EXCEPTION 'Federal wave F8: % roll(s) have a yea+nay pool smaller than the number of attributed yea/nay rows. The attributed set is a subset of the chamber, so this means the totals were recomputed from the rows.', n_tally;
  END IF;

  -- And the check that catches a roster-derived total, which is the failure worth fearing:
  -- it would publish a vote that did not happen, with a plausible-looking margin. Every
  -- roll here is a Senate roll accounting for 99 or 100 seats. The roster admits 101
  -- senators across three Congresses, so a total assembled from the rows misses the bound.
  -- present/notVoting are coalesced because one roll (119/1/127, S. 331, 84-16) stores
  -- totals with neither key rather than with zeros, and rewriting stored totals to tidy a
  -- guard would be this migration overwriting data it came to read.
  SELECT count(*) INTO n_chamber FROM vr_rollcalls r
   WHERE r.id = ANY(roll_ids)
     AND (r.totals->>'yea')::int + (r.totals->>'nay')::int
       + coalesce((r.totals->>'present')::int, 0) + coalesce((r.totals->>'notVoting')::int, 0)
       NOT BETWEEN 99 AND 100;
  IF n_chamber > 0 THEN
    RAISE EXCEPTION 'Federal wave F8: % roll(s) do not account for a full Senate. A Senate roll totals 99-100; anything near the roster size is the attributed subset masquerading as the chamber.', n_chamber;
  END IF;

  -- Rule 11 in the migration and not only in the harness, because the bug it catches lives
  -- in the LIS path this wave read from: <vote_tally> renders '51-42' as a DISPLAY STRING,
  -- and read as a number that is 5142, which makes the losing side zero and every roll look
  -- unanimous. The authority is the <count><yeas>/<nays> block. This wave admits no roll, so
  -- the guard is here to protect the rolls it WRITES INTO from a re-pull under that bug.
  SELECT count(*) INTO n_rule11 FROM vr_rollcalls r
   WHERE r.id = ANY(roll_ids)
     AND 10 * least((r.totals->>'yea')::int, (r.totals->>'nay')::int)
         < (r.totals->>'yea')::int + (r.totals->>'nay')::int;
  IF n_rule11 > 0 THEN
    RAISE EXCEPTION 'Federal wave F8: % roll(s) fail rule 11 — the losing side is under a tenth of the yea+nay pool.', n_rule11;
  END IF;

  -- Attribution-only, asserted from the other side. This wave writes no measure and no
  -- issue mapping, so the measure count behind these rolls and the issue-row count on those
  -- measures are both frozen at what they were before it ran. If a later edit to this file
  -- quietly grows a measure or a key, these two fire.
  SELECT count(DISTINCT measure_id) INTO n_measures FROM vr_rollcalls WHERE id = ANY(roll_ids);
  IF n_measures <> 73 THEN
    RAISE EXCEPTION 'Federal wave F8: expected 73 distinct measures behind these rolls, found %', n_measures;
  END IF;

  SELECT count(*) INTO n_issues FROM vr_measure_issues
   WHERE measure_id IN (SELECT measure_id FROM vr_rollcalls WHERE id = ANY(roll_ids));
  IF n_issues <> 197 THEN
    RAISE EXCEPTION 'Federal wave F8: expected the 197 pre-existing issue rows on these measures to be untouched, found %. This wave creates and changes no issue mapping.', n_issues;
  END IF;

  RAISE NOTICE 'Federal wave F8 verified: % cells for 3 newly admitted senators across % Senate roll calls already on file; 0 measures, 0 roll calls, 0 issue mappings, 0 new keys. Senate energy pool after refusal-first: empty.', n_cells, n_rolls;
END $$;
